def anunciar(func):
    def wrapper(*args, **kwargs):
        print("Empezando...")
        resultado = func(*args, **kwargs)
        print("Terminado.")
        return resultado
    return wrapper

@anunciar
def saludar(nombre):
    return f"Hola, {nombre}!"

print(saludar("Sofia"))

